const vendor='/vendor/pdfjs-6.4.299/';let library;
async function engine(){if(!library)library=import(vendor+'legacy/build/pdf.min.mjs').then(pdf=>{pdf.GlobalWorkerOptions.workerSrc=vendor+'legacy/build/pdf.worker.min.mjs';return pdf}).catch(error=>{library=null;throw error});return library;}
export function initPage(){
 const config=document.querySelector('[data-document-copy]');if(!config)return;const copy=JSON.parse(config.textContent);
 let dialog,stage,status,title,download,print,previous,next,counter,zoom,retry,text,loadingTask,pdf,renderTask,printFrame,source,opener,pageNumber=1,session=0,renderId=0,active=true,printReady=false,printing=false,printUrls=[],resizeTimer;
 function message(key,values={}){return Object.entries(values).reduce((s,[k,v])=>s.replaceAll('{'+k+'}',v),copy[key]);}
 function node(tag,cls,textContent){const el=document.createElement(tag);if(cls)el.className=cls;if(textContent)el.textContent=textContent;return el;}
 function button(label,handler){const el=node('button','',label);el.type='button';el.addEventListener('click',handler);return el;}
 function build(){if(dialog)return;dialog=node('dialog','document-viewer');dialog.setAttribute('aria-labelledby','document-viewer-title');const toolbar=node('div','document-toolbar');title=node('h2');title.id='document-viewer-title';const actions=node('div','document-toolbar-actions');download=node('a','document-download',copy.download);download.dataset.documentDownload='';print=button(copy.print,preparePrint);print.dataset.documentPrint='';const close=button(copy.close+' ×',()=>dialog.close());close.dataset.documentClose='';actions.append(download,print,close);toolbar.append(title,actions);
 const controls=node('div','document-controls'),pages=node('div','document-page-controls');previous=button('←',()=>turn(-1));previous.setAttribute('aria-label',copy.previous);previous.dataset.documentPrevious='';next=button('→',()=>turn(1));next.setAttribute('aria-label',copy.next);next.dataset.documentNext='';counter=node('span');counter.dataset.documentPage='';counter.setAttribute('aria-live','polite');pages.append(previous,counter,next);const label=node('label','',copy.zoom);zoom=node('select');zoom.dataset.documentZoom='';for(const [value,name] of [['fit',copy.fit],['1.25','125%'],['1.5','150%'],['2','200%']]){const option=node('option','',name);option.value=value;zoom.append(option);}zoom.addEventListener('change',()=>draw());label.append(zoom);controls.append(pages,label);
 status=node('p','document-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.dataset.documentStatus='';retry=button(copy.retry,()=>load(source));retry.hidden=true;retry.dataset.documentRetry='';stage=node('div','document-stage');stage.tabIndex=0;stage.setAttribute('role','region');stage.setAttribute('aria-label',copy.region);stage.dataset.documentStage='';const note=node('p','document-note',copy.note),details=node('details'),summary=node('summary','',copy.text);text=node('p');text.dataset.documentText='';details.append(summary,text);dialog.append(toolbar,controls,status,retry,stage,details,note);document.body.append(dialog);
 dialog.addEventListener('close',()=>{clearDocument();document.documentElement.classList.remove('document-viewer-open');if(opener?.isConnected)opener.focus({preventScroll:true});});
 dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
 dialog.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||event.shiftKey||event.target.closest('select,input,button,a,summary')||zoom.value!=='fit')return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();turn(event.key==='ArrowLeft'?-1:1);}});
 }
 function cleanPrint(){printFrame?.remove();printFrame=null;for(const url of printUrls)URL.revokeObjectURL(url);printUrls=[];printReady=false;printing=false;}
 function clearDocument(){session++;renderId++;renderTask?.cancel();renderTask=null;clearTimeout(resizeTimer);cleanPrint();const old=loadingTask;loadingTask=null;pdf=null;if(old)Promise.resolve(old.destroy()).catch(()=>{});stage?.replaceChildren();stage?.removeAttribute('aria-busy');}
 function controls(){previous.disabled=!pdf||pageNumber<=1;next.disabled=!pdf||pageNumber>=pdf.numPages;zoom.disabled=!pdf;print.disabled=!pdf||printing;counter.textContent=pdf?message('page',{n:pageNumber,total:pdf.numPages}):'';}
 async function load(url){clearDocument();source=url;const token=session;status.textContent=copy.loading;retry.hidden=true;text.textContent='';text.closest('details').open=false;zoom.value='fit';pageNumber=1;print.textContent=copy.print;controls();
 try{const lib=await engine();if(!active||token!==session)return;loadingTask=lib.getDocument({url:url.href,cMapUrl:vendor+'cmaps/',cMapPacked:true,standardFontDataUrl:vendor+'standard_fonts/',wasmUrl:vendor+'wasm/',iccUrl:vendor+'iccs/',isEvalSupported:false});pdf=await loadingTask.promise;if(!active||token!==session)return;controls();await draw();}catch(error){if(!active||token!==session)return;status.textContent=copy.error;retry.hidden=false;controls();}}
 async function draw(){if(!pdf||!dialog.open)return;const token=session,id=++renderId;renderTask?.cancel();status.textContent=copy.rendering;stage.setAttribute('aria-busy','true');
 try{const page=await pdf.getPage(pageNumber);if(token!==session||id!==renderId)return;const base=page.getViewport({scale:1}),fit=Math.max(200,stage.clientWidth-(innerWidth<=760?20:32))/base.width,scale=fit*(zoom.value==='fit'?1:Number(zoom.value)),viewport=page.getViewport({scale}),ratio=Math.min(devicePixelRatio||1,2,Math.sqrt(8000000/(viewport.width*viewport.height))),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.floor(viewport.width*ratio));canvas.height=Math.max(1,Math.floor(viewport.height*ratio));canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';canvas.setAttribute('role','img');canvas.setAttribute('aria-label',message('image',{n:pageNumber,total:pdf.numPages}));
 const task=renderTask=page.render({canvasContext:canvas.getContext('2d'),viewport,transform:ratio!==1?[ratio,0,0,ratio,0,0]:null});await task.promise;if(token!==session||id!==renderId)return;stage.replaceChildren(canvas);stage.scrollTop=0;stage.scrollLeft=0;stage.removeAttribute('aria-busy');const content=await page.getTextContent();if(token!==session||id!==renderId)return;text.textContent=content.items.map(item=>item.str||'').join(' ').trim()||copy.noText;status.textContent='';controls();
 }catch(error){if(token!==session||id!==renderId||error.name==='RenderingCancelledException')return;stage.removeAttribute('aria-busy');status.textContent=copy.error;retry.hidden=false;}}
 function turn(delta){if(!pdf)return;const n=Math.max(1,Math.min(pdf.numPages,pageNumber+delta));if(n===pageNumber)return;pageNumber=n;controls();draw();}
 async function preparePrint(){if(!pdf||printing)return;if(printReady&&printFrame){try{printFrame.contentWindow.focus();printFrame.contentWindow.print();print.focus({preventScroll:true});status.textContent=copy.printStarted;}catch{status.textContent=copy.printError;}return;}
 printing=true;print.disabled=true;status.textContent=copy.printing;const token=session,documentPdf=pdf;
 try{const frame=printFrame=document.createElement('iframe');frame.className='document-print-frame';frame.title=copy.printReady;frame.setAttribute('aria-hidden','true');frame.tabIndex=-1;frame.src='about:blank';dialog.append(frame);const doc=frame.contentDocument;doc.open();doc.write('<!doctype html><html><head><meta charset="utf-8"><title></title><style>html,body{margin:0;padding:0}section{break-after:page;page-break-after:always}section:last-child{break-after:auto;page-break-after:auto}img{display:block;width:100%;height:100%;object-fit:contain}@media screen{section{max-width:100%}}</style></head><body></body></html>');doc.close();doc.title=title.textContent;doc.documentElement.lang=document.documentElement.lang;
 for(let n=1;n<=documentPdf.numPages;n++){if(token!==session||!active)return;const page=await documentPdf.getPage(n),base=page.getViewport({scale:1}),scale=Math.min(2,Math.sqrt(8000000/(base.width*base.height))),viewport=page.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),viewport,intent:'print'}).promise;const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Print image failed')),'image/png'));canvas.width=canvas.height=1;if(token!==session||!active)return;const url=URL.createObjectURL(blob);printUrls.push(url);const section=doc.createElement('section'),image=doc.createElement('img');section.style.cssText='width:'+base.width+'pt;height:'+base.height+'pt;page:source-page-'+n;const css=doc.createElement('style');css.textContent='@page source-page-'+n+'{size:'+base.width+'pt '+base.height+'pt;margin:0}';doc.head.append(css);image.src=url;image.alt=message('image',{n,total:documentPdf.numPages});section.append(image);doc.body.append(section);await image.decode();}
 if(token!==session||!active)return;printReady=true;printing=false;print.disabled=false;print.textContent=copy.printReady;status.textContent=copy.printPrepared;
 }catch{if(token!==session||!active)return;cleanPrint();print.disabled=false;status.textContent=copy.printError;}}
 function click(event){const link=event.target.closest?.('a[href]');if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||link.hasAttribute('download'))return;let url;try{url=new URL(link.href,location.href)}catch{return}if(url.origin!==location.origin||!url.pathname.toLowerCase().endsWith('.pdf'))return;event.preventDefault();event.stopPropagation();build();opener=link;source=url;source.hash='';title.textContent=link.dataset.documentTitle||link.closest('[data-article-reader]')?.dataset.readerTitle||link.closest('article')?.querySelector('h3')?.textContent||link.closest('.legacy-preview-dialog')?.querySelector('h2')?.textContent||document.querySelector('main h1')?.textContent||copy.title;download.href=source.href;download.setAttribute('download',source.pathname.split('/').pop());document.documentElement.classList.add('document-viewer-open');if(!dialog.open)dialog.showModal();dialog.querySelector('[data-document-close]').focus();load(source);}
 document.addEventListener('click',click);window.addEventListener('resize',()=>{if(!dialog?.open||zoom.value!=='fit')return;clearTimeout(resizeTimer);resizeTimer=setTimeout(draw,180);});
 const leave=()=>{active=false;if(dialog?.open)dialog.close();else clearDocument();dialog?.remove();document.documentElement.classList.remove('document-viewer-open');document.removeEventListener('click',click);};if(window.MTPageRouter)window.MTPageRouter.onLeave(leave);else window.addEventListener('pagehide',leave,{once:true});
}
if(!window.MTPageRouter?.booting){if(window.MTPageRouter)window.MTPageRouter.run(initPage);else initPage();}
